alter table public.assets enable row level security; alter table public.prices enable row level security; alter table public.macro_signals enable row level security; alter table public.news enable row level security; alter table public.profiles enable row level security; alter table public.lots enable row level security; alter table public.alerts enable row level security; alter table public.alert_history enable row level security;
create policy "public read assets" on public.assets for select using (true); create policy "public read prices" on public.prices for select using (true); create policy "public read macro signals" on public.macro_signals for select using (true); create policy "public read news" on public.news for select using (true);
create policy "users read own profile" on public.profiles for select using (auth.uid() = id); create policy "users insert own profile" on public.profiles for insert with check (auth.uid() = id); create policy "users update own profile" on public.profiles for update using (auth.uid() = id) with check (auth.uid() = id); create policy "users delete own profile" on public.profiles for delete using (auth.uid() = id);
create policy "users manage own lots" on public.lots for all using (auth.uid() = user_id) with check (auth.uid() = user_id); create policy "users manage own alerts" on public.alerts for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "users read own alert history" on public.alert_history for select using (exists (select 1 from public.alerts a where a.id = alert_id and a.user_id = auth.uid()));
-- No anonymous or authenticated write policies exist for market data: only service_role bypasses RLS.
